CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS connections(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, provider TEXT NOT NULL CHECK(provider IN ('openai','anthropic','codex')), label TEXT NOT NULL, secret TEXT NOT NULL, status TEXT NOT NULL, models TEXT NOT NULL DEFAULT '[]', metadata TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS agents(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, name TEXT NOT NULL, normalized_name TEXT NOT NULL UNIQUE, provider TEXT NOT NULL, connection_id TEXT REFERENCES connections(id) ON DELETE SET NULL, model TEXT NOT NULL, instructions TEXT NOT NULL DEFAULT '', origin TEXT NOT NULL DEFAULT 'loop', created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, agent_id TEXT REFERENCES agents(id), title TEXT NOT NULL, origin TEXT NOT NULL DEFAULT 'loop', external_id TEXT, created_at INTEGER NOT NULL, UNIQUE(owner_id,origin,external_id));
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, agent_id TEXT REFERENCES agents(id), conversation_id TEXT REFERENCES conversations(id), kind TEXT NOT NULL DEFAULT 'agent', input TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','running','pausing','paused','awaiting_approval','completed','failed','cancelled','interrupted')), idempotency_key TEXT NOT NULL, payload TEXT NOT NULL DEFAULT '{}', result TEXT, error TEXT, worker_id TEXT, heartbeat INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(owner_id,idempotency_key));
CREATE INDEX IF NOT EXISTS run_queue ON runs(state,created_at);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id TEXT NOT NULL, run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE, type TEXT NOT NULL, payload TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS event_cursor ON events(owner_id,id);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, run_id TEXT REFERENCES runs(id), role TEXT NOT NULL, content TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS folders(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, parent_id TEXT REFERENCES folders(id), kind TEXT NOT NULL CHECK(kind IN ('project','folder')), name TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS artifacts(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, agent_id TEXT REFERENCES agents(id), conversation_id TEXT REFERENCES conversations(id), run_id TEXT REFERENCES runs(id), title TEXT NOT NULL, kind TEXT NOT NULL, content TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', folder_id TEXT REFERENCES folders(id), pinned INTEGER NOT NULL DEFAULT 0, archived INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS artifact_versions(id TEXT PRIMARY KEY, artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE, version INTEGER NOT NULL, content TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(artifact_id,version));
CREATE TABLE IF NOT EXISTS operations(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE, previous TEXT NOT NULL, expected_version INTEGER NOT NULL, undone INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS imports(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, provider TEXT NOT NULL, digest TEXT NOT NULL, status TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, UNIQUE(owner_id,digest));
CREATE TABLE IF NOT EXISTS workflows(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, title TEXT NOT NULL, version INTEGER NOT NULL, source TEXT NOT NULL, compiled TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(id,version));
CREATE TABLE IF NOT EXISTS workflow_versions(workflow_id TEXT NOT NULL REFERENCES workflows(id) ON DELETE CASCADE, version INTEGER NOT NULL, source TEXT NOT NULL, compiled TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(workflow_id,version));
CREATE TABLE IF NOT EXISTS mcp_connections(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, name TEXT NOT NULL, url TEXT NOT NULL, secret TEXT NOT NULL, status TEXT NOT NULL, tools TEXT NOT NULL DEFAULT '[]', metadata TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS grants(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, agent_id TEXT NOT NULL REFERENCES agents(id), connection_id TEXT NOT NULL REFERENCES mcp_connections(id) ON DELETE CASCADE, tool TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('ask','allow')), UNIQUE(agent_id,connection_id,tool));
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, run_id TEXT NOT NULL REFERENCES runs(id), digest TEXT NOT NULL, request TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','approved','rejected','executing','completed','unknown')), result TEXT, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS search_vectors(artifact_id TEXT PRIMARY KEY REFERENCES artifacts(id) ON DELETE CASCADE, owner_id TEXT NOT NULL, model TEXT NOT NULL, vector TEXT NOT NULL, content_hash TEXT NOT NULL);
CREATE VIRTUAL TABLE IF NOT EXISTS artifact_fts USING fts5(artifact_id UNINDEXED, owner_id UNINDEXED, title, content, tokenize='unicode61');
CREATE TRIGGER IF NOT EXISTS artifact_insert AFTER INSERT ON artifacts BEGIN INSERT INTO artifact_fts(artifact_id,owner_id,title,content) VALUES(new.id,new.owner_id,new.title,new.content); END;
CREATE TRIGGER IF NOT EXISTS artifact_update AFTER UPDATE ON artifacts BEGIN DELETE FROM artifact_fts WHERE artifact_id=old.id; INSERT INTO artifact_fts(artifact_id,owner_id,title,content) VALUES(new.id,new.owner_id,new.title,new.content); END;
CREATE TRIGGER IF NOT EXISTS artifact_delete AFTER DELETE ON artifacts BEGIN DELETE FROM artifact_fts WHERE artifact_id=old.id; END;
INSERT OR IGNORE INTO schema_version VALUES(1,unixepoch()*1000);
